class Singleton:
    """Singleton pattern - ensures only one instance exists"""
    _instance = None
    _initialized = False

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self, name="Default"):
        if not self._initialized:
            self.name = name
            self._initialized = True

    def get_info(self):
        return f"Singleton instance: {self.name}"

# Alternative implementation using metaclass
class SingletonMeta(type):
    """Metaclass for creating singleton classes"""
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class Database(metaclass=SingletonMeta):
    def __init__(self, connection_string):
        self.connection_string = connection_string
        self.connected = False

    def connect(self):
        if not self.connected:
            print(f"Connecting to {self.connection_string}")
            self.connected = True
        return self.connected

    def query(self, sql):
        if not self.connected:
            raise ConnectionError("Not connected to database")
        return f"Executed: {sql}"

# Usage
# Method 1: Using __new__
singleton1 = Singleton("First")
singleton2 = Singleton("Second")
print(f"singleton1 is singleton2: {singleton1 is singleton2}")  # True
print(singleton1.get_info())  # Singleton instance: First
print(singleton2.get_info())  # Singleton instance: First

# Method 2: Using metaclass
db1 = Database("mysql://localhost:3306/mydb")
db2 = Database("postgres://localhost:5432/mydb")
print(f"db1 is db2: {db1 is db2}")  # True
print(f"db1.connection_string: {db1.connection_string}")  # mysql://localhost:3306/mydb
print(f"db2.connection_string: {db2.connection_string}")  # mysql://localhost:3306/mydb
