from abc import ABC, abstractmethod

class Animal(ABC):
    @abstractmethod
    def make_sound(self):
        pass

    @abstractmethod
    def get_info(self):
        pass

class Dog(Animal):
    def make_sound(self):
        return "Woof!"

    def get_info(self):
        return "I am a dog"

class Cat(Animal):
    def make_sound(self):
        return "Meow!"

    def get_info(self):
        return "I am a cat"

class Bird(Animal):
    def make_sound(self):
        return "Tweet!"

    def get_info(self):
        return "I am a bird"

# Simple Factory
class AnimalFactory:
    @staticmethod
    def create_animal(animal_type):
        if animal_type.lower() == "dog":
            return Dog()
        elif animal_type.lower() == "cat":
            return Cat()
        elif animal_type.lower() == "bird":
            return Bird()
        else:
            raise ValueError(f"Unknown animal type: {animal_type}")

# Factory Method Pattern
class AnimalCreator(ABC):
    @abstractmethod
    def create_animal(self) -> Animal:
        pass

class DogCreator(AnimalCreator):
    def create_animal(self) -> Animal:
        return Dog()

class CatCreator(AnimalCreator):
    def create_animal(self) -> Animal:
        return Cat()

class BirdCreator(AnimalCreator):
    def create_animal(self) -> Animal:
        return Bird()

# Abstract Factory Pattern
class Pet(ABC):
    @abstractmethod
    def play(self):
        pass

class WildAnimal(ABC):
    @abstractmethod
    def hunt(self):
        pass

class PetDog(Dog, Pet):
    def play(self):
        return "Playing fetch"

class WildDog(Dog, WildAnimal):
    def hunt(self):
        return "Hunting in the wild"

class PetCat(Cat, Pet):
    def play(self):
        return "Playing with yarn"

class WildCat(Cat, WildAnimal):
    def hunt(self):
        return "Hunting mice"

class AnimalAbstractFactory(ABC):
    @abstractmethod
    def create_pet(self) -> Pet:
        pass

    @abstractmethod
    def create_wild_animal(self) -> WildAnimal:
        pass

class DogFactory(AnimalAbstractFactory):
    def create_pet(self) -> Pet:
        return PetDog()

    def create_wild_animal(self) -> WildAnimal:
        return WildDog()

class CatFactory(AnimalAbstractFactory):
    def create_pet(self) -> Pet:
        return PetCat()

    def create_wild_animal(self) -> WildAnimal:
        return WildCat()

# Usage
# Simple Factory
factory = AnimalFactory()
dog = factory.create_animal("dog")
cat = factory.create_animal("cat")
print(f"Dog: {dog.make_sound()}")
print(f"Cat: {cat.make_sound()}")

# Factory Method
dog_creator = DogCreator()
cat_creator = CatCreator()
dog = dog_creator.create_animal()
cat = cat_creator.create_animal()
print(f"Dog: {dog.get_info()}")
print(f"Cat: {cat.get_info()}")

# Abstract Factory
dog_factory = DogFactory()
cat_factory = CatFactory()

pet_dog = dog_factory.create_pet()
wild_dog = dog_factory.create_wild_animal()
pet_cat = cat_factory.create_pet()
wild_cat = cat_factory.create_wild_animal()

print(f"Pet dog: {pet_dog.play()}")
print(f"Wild dog: {wild_dog.hunt()}")
print(f"Pet cat: {pet_cat.play()}")
print(f"Wild cat: {wild_cat.hunt()}")
```

