from abc import ABC, abstractmethod

class Observer(ABC):
    @abstractmethod
    def update(self, subject):
        pass

class Subject(ABC):
    def __init__(self):
        self._observers = []
        self._state = None

    def attach(self, observer: Observer):
        if observer not in self._observers:
            self._observers.append(observer)

    def detach(self, observer: Observer):
        self._observers.remove(observer)

    def notify(self):
        for observer in self._observers:
            observer.update(self)

    @property
    def state(self):
        return self._state

    @state.setter
    def state(self, value):
        self._state = value
        self.notify()

class StockPrice(Subject):
    def __init__(self, symbol, price):
        super().__init__()
        self.symbol = symbol
        self._state = price

    def set_price(self, price):
        self.state = price

class StockDisplay(Observer):
    def __init__(self, name):
        self.name = name

    def update(self, subject):
        print(f"{self.name}: {subject.symbol} is now ${subject.state}")

class StockAlert(Observer):
    def __init__(self, name, threshold):
        self.name = name
        self.threshold = threshold

    def update(self, subject):
        if subject.state > self.threshold:
            print(f"{self.name}: ALERT! {subject.symbol} is above ${self.threshold} (${subject.state})")

class StockLogger(Observer):
    def __init__(self, filename):
        self.filename = filename

    def update(self, subject):
        with open(self.filename, 'a') as f:
            f.write(f"{subject.symbol}: ${subject.state}\n")

# Usage
stock = StockPrice("AAPL", 150.00)

display1 = StockDisplay("Display 1")
display2 = StockDisplay("Display 2")
alert = StockAlert("High Price Alert", 160.00)
logger = StockLogger("stock_log.txt")

stock.attach(display1)
stock.attach(display2)
stock.attach(alert)
stock.attach(logger)

print("Stock price updates:")
stock.set_price(155.00)
stock.set_price(165.00)
stock.set_price(170.00)

# Detach an observer
stock.detach(display2)
stock.set_price(175.00)
```

