from abc import ABC, abstractmethod

class Coffee(ABC):
    @abstractmethod
    def cost(self):
        pass

    @abstractmethod
    def description(self):
        pass

class SimpleCoffee(Coffee):
    def cost(self):
        return 2.00

    def description(self):
        return "Simple coffee"

class CoffeeDecorator(Coffee):
    def __init__(self, coffee: Coffee):
        self._coffee = coffee

    def cost(self):
        return self._coffee.cost()

    def description(self):
        return self._coffee.description()

class Milk(CoffeeDecorator):
    def cost(self):
        return self._coffee.cost() + 0.50

    def description(self):
        return self._coffee.description() + ", milk"

class Sugar(CoffeeDecorator):
    def cost(self):
        return self._coffee.cost() + 0.25

    def description(self):
        return self._coffee.description() + ", sugar"

class Whip(CoffeeDecorator):
    def cost(self):
        return self._coffee.cost() + 0.75

    def description(self):
        return self._coffee.description() + ", whip"

class Vanilla(CoffeeDecorator):
    def cost(self):
        return self._coffee.cost() + 1.00

    def description(self):
        return self._coffee.description() + ", vanilla"

# Usage
coffee = SimpleCoffee()
print(f"Cost: ${coffee.cost()}, Description: {coffee.description()}")

# Add milk
coffee_with_milk = Milk(coffee)
print(f"Cost: ${coffee_with_milk.cost()}, Description: {coffee_with_milk.description()}")

# Add sugar
coffee_with_milk_sugar = Sugar(coffee_with_milk)
print(f"Cost: ${coffee_with_milk_sugar.cost()}, Description: {coffee_with_milk_sugar.description()}")

# Add whip and vanilla
fancy_coffee = Whip(Vanilla(coffee_with_milk_sugar))
print(f"Cost: ${fancy_coffee.cost()}, Description: {fancy_coffee.description()}")
