from abc import ABC, abstractmethod

class Command(ABC):
    @abstractmethod
    def execute(self):
        pass

    @abstractmethod
    def undo(self):
        pass

class Light:
    def __init__(self, location):
        self.location = location
        self.is_on = False

    def turn_on(self):
        self.is_on = True
        return f"{self.location} light is ON"

    def turn_off(self):
        self.is_on = False
        return f"{self.location} light is OFF"

    def get_status(self):
        return f"{self.location} light is {'ON' if self.is_on else 'OFF'}"

class LightOnCommand(Command):
    def __init__(self, light: Light):
        self.light = light

    def execute(self):
        return self.light.turn_on()

    def undo(self):
        return self.light.turn_off()

class LightOffCommand(Command):
    def __init__(self, light: Light):
        self.light = light

    def execute(self):
        return self.light.turn_off()

    def undo(self):
        return self.light.turn_on()

class RemoteControl:
    def __init__(self):
        self.commands = {}
        self.last_command = None

    def set_command(self, slot, command: Command):
        self.commands[slot] = command

    def press_button(self, slot):
        if slot in self.commands:
            command = self.commands[slot]
            self.last_command = command
            return command.execute()
        return "No command set for this slot"

    def press_undo(self):
        if self.last_command:
            return self.last_command.undo()
        return "No command to undo"

# Usage
living_room_light = Light("Living Room")
kitchen_light = Light("Kitchen")

living_room_on = LightOnCommand(living_room_light)
living_room_off = LightOffCommand(living_room_light)
kitchen_on = LightOnCommand(kitchen_light)
kitchen_off = LightOffCommand(kitchen_light)

remote = RemoteControl()
remote.set_command(1, living_room_on)
remote.set_command(2, living_room_off)
remote.set_command(3, kitchen_on)
remote.set_command(4, kitchen_off)

print("Remote control operations:")
print(remote.press_button(1))  # Turn on living room
print(remote.press_button(3))  # Turn on kitchen
print(remote.press_undo())     # Undo last command
print(remote.press_button(2))  # Turn off living room
print(living_room_light.get_status())
print(kitchen_light.get_status())
```

