# Existing interface
class OldSystem:
    def specific_request(self):
        return "Old system specific request"

# New interface
class NewSystem:
    def request(self):
        return "New system request"

# Adapter to make old system work with new interface
class Adapter:
    def __init__(self, old_system: OldSystem):
        self.old_system = old_system

    def request(self):
        # Convert old system response to new format
        old_response = self.old_system.specific_request()
        return f"Adapted: {old_response}"

# Client code that expects new interface
class Client:
    def __init__(self, system):
        self.system = system

    def make_request(self):
        return self.system.request()

# Usage
old_system = OldSystem()
new_system = NewSystem()

# Use new system directly
client1 = Client(new_system)
print(client1.make_request())  # New system request

# Use old system through adapter
adapter = Adapter(old_system)
client2 = Client(adapter)
print(client2.make_request())  # Adapted: Old system specific request
```
